script:
export const meta = {
  name: 'h0x-phase',
  description: 'H0x Video Studio phase loop: plan -> develop (1-3 devs) -> write tests -> run tests -> fix until green -> update docs',
  whenToUse: 'Run one H0x phase goal. args: { goal, date, maxDevs?: 1-3, seed?: string, subtasks?: [] }',
  phases: [
    { title: 'Plan', detail: 'planner splits goal into subtasks; orchestrator assigns tools' },
    { title: 'Build', detail: 'per layer: develop -> tests -> run -> fix until green' },
    { title: 'Record', detail: 'orchestrator updates HANDOFF, TODO, ADR' },
  ],
}

const goal = args && args.goal
if (!goal) throw new Error('args.goal is required')
const maxDevs = Math.min(3, Math.max(1, (args && args.maxDevs) || 3))
const MAX_FIX_ROUNDS = 3

const SUBTASKS = {
  type: 'object',
  properties: {
    subtasks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          title: { type: 'string' },
          files: { type: 'array', items: { type: 'string' } },
          acceptance: { type: 'array', items: { type: 'string' } },
          dependsOn: { type: 'array', items: { type: 'string' } },
          tools: { type: 'string' },
        },
        required: ['id', 'title', 'files', 'acceptance', 'dependsOn'],
      },
    },
    questions: { type: 'array', items: { type: 'string' } },
  },
  required: ['subtasks', 'questions'],
}

const REPORT = {
  type: 'object',
  properties: {
    passed: { type: 'boolean' },
    failures: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          test: { type: 'string' },
          error: { type: 'string' },
          cause: { type: 'string' },
          file: { type: 'string' },
          preexisting: { type: 'boolean' },
        },
        required: ['test', 'error', 'cause'],
      },
    },
    summary: { type: 'string' },
  },
  required: ['passed', 'failures', 'summary'],
}

// This session's agent types point at older docs, so every prompt names the workspace.
const WS = `Workspace: E:/research-clones/h0x-video-studio. Product code: E:/research-clones/h0x-video-studio/app (git repo, branch main). Records: E:/research-clones/h0x-video-studio/docs/agents (ADR.md, HANDOFF.md, TOOLS.md) and E:/research-clones/h0x-video-studio/TODO.md - NOT E:/research-clones/docs/agents. Your role file: E:/research-clones/h0x-video-studio/.claude/agents/<role>.md - read it first and follow it over any older instructions. RAM rule (8 GB laptop): never run cargo (check/build/test/tree) unless your subtask id is exactly "A2"; other Rust subtasks verify with git grep only and report "cargo deferred to A2". Never run nx build. Run frontend tests only for the projects you touched, with --skip-sync. Never commit or push.

`
const run = (prompt, opts) => agent(WS + prompt, opts)

// A Rust subtask that may not compile (RAM rule) reports no failures and says cargo is deferred: pending, not red.
const deferred = r => !r.passed && r.failures.length === 0 && /deferred to A2|RAM rule/i.test(r.summary)
const deferredNotes = []

const fmt = t => `${t.id} "${t.title}"\nFiles: ${t.files.join(', ')}\nAcceptance:\n- ${t.acceptance.join('\n- ')}\nTool hints: ${t.tools || 'see TOOLS.md'}`

phase('Plan')
// args.subtasks: an already-approved plan (e.g. a previous planner run grouped into work packages) skips re-planning.
let assigned = args.subtasks ? { subtasks: args.subtasks, questions: [] } : null
if (!assigned && args.subtasksFile) {
  assigned = await run(
    `Read the JSON array in ${args.subtasksFile} and return it verbatim as "subtasks" (questions: []). Do not change any field.`,
    { agentType: 'planner', label: 'planner:load', schema: SUBTASKS, effort: 'low' })
}
if (!assigned) {
  const plan = await run(`Goal: ${goal}\nSplit it into subtasks.${args.seed ? `\nSeed subtasks to refine (keep ids where sensible):\n${args.seed}` : ''}`, { agentType: 'planner', label: 'planner', schema: SUBTASKS })
  if (plan.questions.length) {
    log(`Planner needs user decisions: ${plan.questions.join(' | ')}`)
    return { status: 'needs-user', questions: plan.questions, subtasks: plan.subtasks }
  }
  assigned = await run(
    `Add a "tools" hint to each subtask per TOOLS.md and return the same list (unchanged otherwise):\n${JSON.stringify(plan.subtasks)}`,
    { agentType: 'orchestrator', label: 'orchestrator:assign', schema: SUBTASKS })
}

// Layering is deterministic code: dependencies first, then no file overlap within a layer, at most maxDevs per layer.
const done = new Set()
let pending = assigned.subtasks.slice()
const layers = []
while (pending.length) {
  const ready = pending.filter(t => t.dependsOn.every(d => done.has(d)))
  if (!ready.length) throw new Error(`Dependency cycle among: ${pending.map(t => t.id).join(', ')}`)
  const layer = [], held = new Set()
  for (const t of ready) {
    if (layer.length >= maxDevs || t.files.some(f => held.has(f))) continue
    t.files.forEach(f => held.add(f))
    layer.push(t)
  }
  layer.forEach(t => done.add(t.id))
  pending = pending.filter(t => !done.has(t.id))
  layers.push(layer)
}
log(`${assigned.subtasks.length} subtasks in ${layers.length} layers (max ${maxDevs} devs)`)

phase('Build')
const results = []
for (let li = 0; li < layers.length; li++) {
  // Each subtask: develop -> write tests -> run -> fix loop. Red blocks the next layer.
  const outcomes = await pipeline(
    layers[li],
    (t, _, i) => run(`Implement subtask:\n${fmt(t)}${t.id === 'A2' && deferredNotes.length ? `\nAlso run every cargo check/test that earlier subtasks deferred to you, and fix what fails:\n${deferredNotes.join('\n---\n')}` : ''}`, { agentType: 'developer', label: `dev-${i + 1}:${t.id}`, phase: 'Build' }),
    (dev, t) => run(`Write edge-case tests for subtask:\n${fmt(t)}\nDeveloper report:\n${dev}`, { agentType: 'test-writer', label: `tests:${t.id}`, phase: 'Build' }),
    async (tests, t, i) => {
      let report = await run(`Run tests for ${t.id}. Test-writer output:\n${tests}`, { agentType: 'test-runner', label: `run:${t.id}`, phase: 'Build', schema: REPORT })
      for (let round = 1; !report.passed && !deferred(report) && round <= MAX_FIX_ROUNDS; round++) {
        const fix = await run(`A failing test report needs a corrective subtask. Code or test wrong? Give the smallest fix instruction.\nSubtask:\n${fmt(t)}\nReport:\n${JSON.stringify(report)}`, { agentType: 'orchestrator', label: `replan:${t.id}#${round}`, phase: 'Build' })
        await run(`Fix round ${round} for subtask:\n${fmt(t)}\nOrchestrator instruction:\n${fix}`, { agentType: 'developer', label: `dev-${i + 1}:fix:${t.id}#${round}`, phase: 'Build' })
        report = await run(`Re-run the tests for ${t.id} (same commands as before).\n${tests}`, { agentType: 'test-runner', label: `rerun:${t.id}#${round}`, phase: 'Build', schema: REPORT })
      }
      if (deferred(report)) deferredNotes.push(`${t.id}: ${report.summary}`)
      return { id: t.id, title: t.title, report }
    },
  )
  const ok = outcomes.filter(Boolean)
  results.push(...ok)
  const red = ok.filter(o => !o.report.passed && !deferred(o.report))
  if (red.length || ok.length < layers[li].length) {
    log(`Layer ${li + 1} still red after ${MAX_FIX_ROUNDS} fix rounds: ${red.map(r => r.id).join(', ') || 'agent dropped'}. Stopping.`)
    phase('Record')
    await run(`Record a BLOCKED run. Goal: ${goal}. Date: ${args.date}. Results: ${JSON.stringify(results)}`, { agentType: 'orchestrator', label: 'orchestrator:record' })
    return { status: 'blocked', layer: li + 1, results }
  }
}

phase('Record')
await run(`Record a completed run. Goal: ${goal}. Date: ${args.date}. Results: ${JSON.stringify(results)}`, { agentType: 'orchestrator', label: 'orchestrator:record' })
return { status: 'green', results }
